begin;
do $$
declare a uuid:=gen_random_uuid();s uuid:=gen_random_uuid();other uuid:=gen_random_uuid();p uuid:=gen_random_uuid();v uuid:=gen_random_uuid();loc uuid;lot uuid:=gen_random_uuid();lot2 uuid:=gen_random_uuid();sale uuid:=gen_random_uuid();res uuid:=gen_random_uuid();sold_res uuid:=gen_random_uuid();res2 uuid:=gen_random_uuid();item uuid;req uuid:=gen_random_uuid();j jsonb;blocked boolean;before_cash numeric;after_cash numeric;begin
 insert into auth.users(id,email) values(a,a::text||'@example.invalid'),(s,s::text||'@example.invalid'),(other,other::text||'@example.invalid');
 update arma_private.user_security set requires_password_change=false,sessions_valid_from=null where user_id in(a,s,other);
 insert into public.user_roles(user_id,role_id) select a,id from public.roles where code='admin' on conflict do nothing;
 insert into public.user_roles(user_id,role_id) select s,id from public.roles where code='seller' on conflict do nothing;
 insert into public.user_roles(user_id,role_id) select other,id from public.roles where code='seller' on conflict do nothing;
 insert into public.products(id,code,name,created_by) values(p,p::text,'TEST CONSIGNMENT PRODUCT',a);
 insert into public.product_variants(id,product_id,sku,size,color,sale_price) values(v,p,v::text,'M','Negro',300);
 select id into loc from public.inventory_locations where is_default and is_active;
 insert into public.inventory_balances(location_id,product_variant_id,physical_quantity,average_unit_cost) values(loc,v,30,100);
 execute 'set local role authenticated';perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated')::text,true);
 perform public.seller_write(jsonb_build_object('request_id',lot,'action','deliver','seller_id',s,'variant_id',v,'quantity',20,'unit_price',200));
 perform public.seller_write(jsonb_build_object('request_id',lot,'action','deliver','seller_id',s,'variant_id',v,'quantity',20,'unit_price',200));
 perform public.seller_write(jsonb_build_object('request_id',lot2,'action','deliver','seller_id',s,'variant_id',v,'quantity',5,'unit_price',220));
 j:=public.seller_overview(s,1);if (j->'summary'->>'physical')::int<>25 or (j->'summary'->>'due')::numeric<>0 then raise exception 'delivery counted as sale or duplicated';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',s,'role','authenticated')::text,true);
 j:=public.scoped_products_page('mine',1,p::text);if (j->>'total')::int<>1 then raise exception 'own product missing';end if;
 j:=public.scoped_product_detail(p,'mine');if jsonb_array_length(j->'product_variants'->0->'consignment_lots')<>2 then raise exception 'delivery prices mixed';end if;
 j:=public.scoped_product_detail(p,'catalog');if j->'product_variants'->0->'inventory_balances'<>'[]'::jsonb then raise exception 'catalog is sellable';end if;
 blocked:=false;begin perform public.create_commerce_order(jsonb_build_object('request_id',gen_random_uuid(),'kind','sale','variant_id',v,'quantity',1,'unit_price',300,'payment_method','cash'));exception when insufficient_privilege then blocked:=true;end;if not blocked then raise exception 'seller sold warehouse stock';end if;
 blocked:=false;begin perform public.create_commerce_order(jsonb_build_object('request_id',gen_random_uuid(),'kind','sale','variant_id',v,'delivery_id',lot,'quantity',1,'unit_price',199,'payment_method','cash'));exception when raise_exception then blocked:=true;end;if not blocked then raise exception 'price below agreement accepted';end if;
 perform public.create_commerce_order(jsonb_build_object('request_id',sale,'kind','sale','variant_id',v,'delivery_id',lot,'quantity',8,'unit_price',300,'payment_method','cash'));
 perform public.create_commerce_order(jsonb_build_object('request_id',sale,'kind','sale','variant_id',v,'delivery_id',lot,'quantity',8,'unit_price',300,'payment_method','cash'));
 if (public.business_dashboard(current_date,current_date)->>'available')::numeric<>17 then raise exception 'dashboard shows another inventory';end if;
 j:=public.seller_overview(null,1);if (j->'summary'->>'due')::numeric<>1600 or (j->'summary'->>'earned')::numeric<>800 then raise exception 'sale obligation or gain incorrect: %',j;end if;
 perform public.create_commerce_order(jsonb_build_object('request_id',res,'kind','reservation','variant_id',v,'delivery_id',lot,'quantity',3,'unit_price',300,'deposit',100,'payment_method','cash','customer_name','TEST Customer'));
 j:=public.seller_overview(null,1);if (j->'summary'->>'due')::numeric<>1600 or (j->'summary'->>'reserved')::int<>3 or (j->'summary'->>'advances')::numeric<>100 then raise exception 'reservation counted as sale';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',other,'role','authenticated')::text,true);
 blocked:=false;begin perform public.create_commerce_order(jsonb_build_object('request_id',gen_random_uuid(),'kind','sale','variant_id',v,'delivery_id',lot,'quantity',1,'unit_price',300,'payment_method','cash'));exception when insufficient_privilege then blocked:=true;end;if not blocked then raise exception 'another seller sold lot';end if;
 blocked:=false;begin perform public.seller_overview(s,1);exception when insufficient_privilege then blocked:=true;end;if not blocked then raise exception 'another seller saw ledger';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated')::text,true);
 perform public.resolve_reservation(res,'complete',sold_res,'transfer',false);
 j:=public.seller_overview(s,1);if (j->'summary'->>'due')::numeric<>2200 or (j->'summary'->>'earned')::numeric<>1100 then raise exception 'reservation completion incorrect';end if;
 select (public.business_dashboard(current_date,current_date)->>'net_receipts')::numeric into before_cash;
 perform public.seller_write(jsonb_build_object('request_id',req,'action','payment','seller_id',s,'amount',1500,'method','transfer'));
 perform public.seller_write(jsonb_build_object('request_id',req,'action','payment','seller_id',s,'amount',1500,'method','transfer'));
 select (public.business_dashboard(current_date,current_date)->>'net_receipts')::numeric into after_cash;if before_cash is distinct from after_cash then raise exception 'seller payment double-counted retail cash';end if;
 execute 'reset role';select id into item from public.commerce_order_items where order_id=sale;execute 'set local role authenticated';
 perform public.commerce_adjust('return',jsonb_build_object('request_id',gen_random_uuid(),'order_id',sale,'item_id',item,'quantity',4,'amount',1200,'method','cash','restock',true,'reason','TEST CUSTOMER RETURN'));
 j:=public.seller_overview(s,1);if (j->'summary'->>'due')::numeric<>-100 or (j->'summary'->>'earned')::numeric<>700 then raise exception 'refund did not create correct credit: %',j;end if;
 perform public.seller_write(jsonb_build_object('request_id',gen_random_uuid(),'action','refund','seller_id',s,'amount',100,'method','cash'));
 perform set_config('request.jwt.claims',jsonb_build_object('sub',s,'role','authenticated')::text,true);
 perform public.create_commerce_order(jsonb_build_object('request_id',gen_random_uuid(),'kind','sale','variant_id',v,'delivery_id',lot2,'quantity',2,'unit_price',350,'payment_method','cash'));
 j:=public.seller_overview(null,1);if (j->'summary'->>'due')::numeric<>440 or (j->'summary'->>'earned')::numeric<>960 then raise exception 'second delivery price not preserved';end if;
 perform public.create_commerce_order(jsonb_build_object('request_id',res2,'kind','reservation','variant_id',v,'delivery_id',lot,'quantity',2,'unit_price',300,'customer_name','TEST Cancel'));
 perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated')::text,true);
 blocked:=false;begin perform public.seller_write(jsonb_build_object('request_id',gen_random_uuid(),'action','return','seller_id',s,'delivery_id',lot,'quantity',12));exception when raise_exception then blocked:=true;end;if not blocked then raise exception 'reserved stock returned to workshop';end if;
 perform public.resolve_reservation(res2,'cancel',gen_random_uuid(),'cash',true);
 perform public.seller_write(jsonb_build_object('request_id',gen_random_uuid(),'action','return','seller_id',s,'delivery_id',lot,'quantity',5));
 j:=public.scoped_product_detail(p,'warehouse');if (j->'product_variants'->0->'inventory_balances'->0->>'available_quantity')::int<>10 then raise exception 'warehouse stock not isolated';end if;
 execute 'reset role';if (select created_by from public.commerce_orders where id=sold_res)<>s then raise exception 'admin completion changed seller';end if;
 if (select average_unit_cost from public.inventory_balances where location_id=loc and product_variant_id=v)<>100 then raise exception 'transfer changed manufacturing cost';end if;
end;$$;
rollback;
